    //A1 + 0~93 每区有94个汉字
    lowCode = (161 + Math.abs(random.nextInt(93))); 

    byte[] b = new byte[2];
    b[0] = (Integer.valueOf(highCode)).byteValue();
    b[1] = (Integer.valueOf(lowCode)).byteValue();

    try {
        str = new String(b, "GBK");
    } catch (UnsupportedEncodingException e) {
        e.printStackTrace();
    }
    return str;
}

