     * 例子:task-pool--1(线程池的数量)
     */
    @Override
    public String getNamePrefix() {
        return "task-pool" + "--" + POOL_NUM.getAndIncrement();
    }
}

@Override
public String getNamePrefix() {
    return "task-pool" + "--" + POOL_NUM.getAndIncrement();
